    compressed_data = zlib.compress(raw_data)
    idat_chunk = b'IDAT' + compressed_data
    idat_len = struct.pack(">I", len(compressed_data))
    idat_crc = struct.pack(">I", zlib.crc32(idat_chunk))
    idat = idat_len + idat_chunk + idat_crc

    # IEND chunk
    iend_chunk = b'IEND'
    iend_len = struct.pack(">I", 0)
    iend_crc = struct.pack(">I", zlib.crc32(iend_chunk))
    iend = iend_len + iend_chunk + iend_crc

    # Combine everything
    png_data = png_sig + ihdr + iccp + idat + iend

