Let’s modify the fuzz harness as follows inside test_server():

```c
// Add this block at the bottom of test_server()
{
	BYTE dummyCertData[512] = {0};
	rdpCertificate cert = { 0 };

	cert.x509 = d2i_X509(NULL, (const BYTE **)&Data, Size);  // Construct a cert from fuzzing input
	if (cert.x509)
