## 🧪 Test Input Plan — Final Form

Now that the harness will directly parse DER certificates, we just need to aggressively feed it valid (and invalid) X.509 blobs.

Here's a final Python script that generates x1.bin to x5.bin inputs targeting malformed policy OIDs.

```python
# final_generate_x509_blobs.py

import os
import struct
import random

def encode_oid(oid_str):
    parts = list(map(int, oid_str.split('.')))
    first = 40 * parts[0] + parts[1]
    rest = parts[2:]
    result = bytearray([first])

    for part in rest:
        if part == 0:
            result.append(0)
            continue
        encoded_part = []
        while part:
            encoded_part.append(part & 0x7F)
            part >>= 7
        for i in reversed(encoded_part[:-1]):
            result.append(i | 0x80)
        result.append(encoded_part[-1])

    return b'\x06' + bytes([len(result)]) + bytes(result)

def make_der_policy_payload(oid="2.23.140.1.2.1", corrupt=False, filler=False):
    der = encode_oid(oid)
    seq = b'\x30' + bytes([len(der)]) + der
    cert = b'\x30'    # Outer SEQUENCE
    content = seq * (50 if filler else 1)
    if corrupt:
        content = bytearray(content)
        for _ in range(10):
            idx = random.randint(0, len(content)-1)
            content[idx] ^= 0xFF
        content = bytes(content)

    cert += bytes([len(content)]) + content
    return cert.ljust(1024, b'\0')

for i in range(5):
    fname = f"x{i+1}.bin"
    if i == 0:
        blob = make_der_policy_payload("2.23.140.1.2.1", corrupt=False)
    elif i == 1:
        blob = make_der_policy_payload("1.2.3.4.5.6", corrupt=False)
    elif i == 2:
        blob = make_der_policy_payload("2.23.140.1.2.1", corrupt=True)
    elif i == 3:
        blob = make_der_policy_payload("2.23.140.1.2.1", corrupt=False, filler=True)
    elif i == 4:
        blob = make_der_policy_payload("2.23.140.1.2.1", corrupt=True, filler=True)

    with open(fname, "wb") as f:
        f.write(blob)
    print(f"[+] Generated {fname} ({len(blob)} bytes)")
```

