  1123	    void killSession(long session, long zxid) {
  1124	        // The list is already removed from the ephemerals,
  1125	        // so we do not have to worry about synchronizing on
  1126	        // the list. This is only called from FinalRequestProcessor
  1127	        // so there is no need for synchronization. The list is not
  1128	        // changed here. Only create and delete change the list which
  1129	        // are again called from FinalRequestProcessor in sequence.
  1130	        killSession(session, zxid, ephemerals.remove(session), null);
  1131	    }
  1132	
  1133	    void killSession(long session, long zxid, Set<String> paths2DeleteLocal,
  1134	            List<String> paths2DeleteInTxn) {
  1135	        if (paths2DeleteInTxn != null) {
  1136	            deleteNodes(session, zxid, paths2DeleteInTxn);
  1137	        }
  1138	
  1139	        if (paths2DeleteLocal == null) {
  1140	            return;
  1141	        }
  1142	
  1143	        if (paths2DeleteInTxn != null) {
  1144	            // explicitly check and remove to avoid potential performance
  1145	            // issue when using removeAll
  1146	            for (String path: paths2DeleteInTxn) {
  1147	                paths2DeleteLocal.remove(path);
  1148	            }
  1149	            if (!paths2DeleteLocal.isEmpty()) {
  1150	                LOG.warn(
  1151	                    "Unexpected extra paths under session {} which are not in txn 0x{}",
  1152	                    paths2DeleteLocal,
  1153	                    Long.toHexString(zxid));
  1154	            }
  1155	        }
  1156	
  1157	        deleteNodes(session, zxid, paths2DeleteLocal);
  1158	    }
