  1160	    void deleteNodes(long session, long zxid, Iterable<String> paths2Delete) {
  1161	        for (String path : paths2Delete) {
  1162	            boolean deleted = false;
  1163	            String sessionHex = "0x" + Long.toHexString(session);
  1164	            try {
  1165	                deleteNode(path, zxid);
  1166	                deleted = true;
  1167	                LOG.debug("Deleting ephemeral node {} for session {}", path, sessionHex);
  1168	            } catch (NoNodeException e) {
  1169	                LOG.warn(
  1170	                    "Ignoring NoNodeException for path {} while removing ephemeral for dead session {}",
  1171	                        path, sessionHex);
  1172	            }
  1173	            if (ZKAuditProvider.isAuditEnabled()) {
  1174	                if (deleted) {
  1175	                    ZKAuditProvider.log(ZKAuditProvider.getZKUser(),
  1176	                            AuditConstants.OP_DEL_EZNODE_EXP, path, null, null,
  1177	                            sessionHex, null, Result.SUCCESS);
  1178	                } else {
  1179	                    ZKAuditProvider.log(ZKAuditProvider.getZKUser(),
  1180	                            AuditConstants.OP_DEL_EZNODE_EXP, path, null, null,
  1181	                            sessionHex, null, Result.FAILURE);
  1182	                }
  1183	            }
  1184	        }
  1185	    }
