  1220	    /**
  1221	     * update the quota for the given path
  1222	     *
  1223	     * @param path the path to be used
  1224	     */
  1225	    private void updateQuotaForPath(String path) {
  1226	        Counts c = new Counts();
  1227	        getCounts(path, c);
  1228	        StatsTrack statsTrack = new StatsTrack();
  1229	        statsTrack.setBytes(c.bytes);
  1230	        statsTrack.setCount(c.count);
  1231	        String statPath = Quotas.statPath(path);
  1232	        DataNode node = getNode(statPath);
  1233	        // it should exist
  1234	        if (node == null) {
  1235	            LOG.warn("Missing quota stat node {}", statPath);
  1236	            return;
  1237	        }
  1238	        synchronized (node) {
  1239	            nodes.preChange(statPath, node);
  1240	            node.data = statsTrack.getStatsBytes();
  1241	            nodes.postChange(statPath, node);
  1242	        }
  1243	    }
  1244	
  1245	    /**
  1246	     * this method traverses the quota path and update the path trie and sets
  1247	     *
  1248	     * @param path the path to be used
  1249	     */
  1250	    private void traverseNode(String path) {
  1251	        DataNode node = getNode(path);
  1252	        String[] children;
  1253	        synchronized (node) {
  1254	            children = node.getChildren().toArray(new String[0]);
  1255	        }
  1256	        if (children.length == 0) {
  1257	            // this node does not have a child
  1258	            // is the leaf node
  1259	            // check if it's the leaf node
  1260	            String endString = "/" + Quotas.limitNode;
  1261	            if (path.endsWith(endString)) {
  1262	                // ok this is the limit node
  1263	                // get the real node and update
  1264	                // the count and the bytes
  1265	                String realPath = path.substring(Quotas.quotaZookeeper.length(), path.indexOf(endString));
  1266	                updateQuotaForPath(realPath);
  1267	                this.pTrie.addPath(realPath);
  1268	            }
  1269	            return;
  1270	        }
  1271	        for (String child : children) {
  1272	            traverseNode(path + "/" + child);
  1273	        }
  1274	    }
