  1333	    public void serializeNodes(OutputArchive oa) throws IOException {
  1334	        serializeNode(oa, new StringBuilder());
  1335	        // / marks end of stream
  1336	        // we need to check if clear had been called in between the snapshot.
  1337	        if (root != null) {
  1338	            oa.writeString("/", "path");
  1339	        }
