  1704	                        digestFromLoadedSnapshot.digestVersion,
  1705	                        Long.toHexString(digestFromLoadedSnapshot.zxid),
  1706	                        digestFromLoadedSnapshot.digest);
  1707	            } else {
  1708	                digestFromLoadedSnapshot = null;
  1709	                LOG.info("The digest value is empty in snapshot");
  1710	            }
