  1807	    /**
  1808	     * Compares the digest of the tree with the digest present in transaction digest.
  1809	     * If there is any error, logs and alerts the watchers.
  1810	     *
  1811	     * @param header transaction header being applied
  1812	     * @param txn    transaction
  1813	     * @param digest transaction digest
  1814	     *
  1815	     * @return false if digest in the txn doesn't match what we have now in the data tree
  1816	     */
  1817	    public boolean compareDigest(TxnHeader header, Record txn, TxnDigest digest) {
  1818	        long zxid = header.getZxid();
  1819	
  1820	        if (!ZooKeeperServer.isDigestEnabled() || digest == null) {
  1821	            return true;
  1822	        }
  1823	        // do not compare digest if we're still in fuzzy state
  1824	        if (digestFromLoadedSnapshot != null) {
  1825	            return true;
  1826	        }
  1827	        // do not compare digest if there is digest version change
  1828	        if (digestCalculator.getDigestVersion() != digest.getVersion()) {
  1829	            RATE_LOGGER.rateLimitLog("Digest version not the same on zxid.", String.valueOf(zxid));
  1830	            return true;
  1831	        }
  1832	
  1833	        long logDigest = digest.getTreeDigest();
  1834	        long actualDigest = getTreeDigest();
  1835	        if (logDigest != actualDigest) {
  1836	            reportDigestMismatch(zxid);
  1837	            LOG.debug("Digest in log: {}, actual tree: {}", logDigest, actualDigest);
  1838	            if (firstMismatchTxn) {
  1839	                LOG.error(
  1840	                        "First digest mismatch on txn: {}, {}, expected digest is {}, actual digest is {}, ",
  1841	                        header, txn, digest, actualDigest);
  1842	                firstMismatchTxn = false;
  1843	            }
  1844	            return false;
  1845	        } else {
  1846	            RATE_LOGGER.flush();
  1847	            LOG.debug(
  1848	                    "Digests are matching for Zxid: {}, Digest in log and actual tree: {}",
  1849	                    Long.toHexString(zxid), logDigest);
  1850	            return true;
  1851	        }
  1852	    }
