   372	     * update the count/bytes of this stat data node
   373	     *
   374	     * @param lastPrefix
   375	     *            the path of the node that has a quota.
   376	     * @param bytesDiff
   377	     *            the diff to be added to number of bytes
   378	     * @param countDiff
   379	     *            the diff to be added to the count
   380	     */
   381	    public void updateQuotaStat(String lastPrefix, long bytesDiff, int countDiff) {
   382	        String statNodePath = Quotas.statPath(lastPrefix);
   383	        DataNode statNode = nodes.get(statNodePath);
   384	
   385	        if (statNode == null) {
   386	            // should not happen
   387	            LOG.error("Missing node for stat {}", statNodePath);
   388	            return;
   389	        }
   390	
   391	        synchronized (statNode) {
   392	            StatsTrack updatedStat = new StatsTrack(statNode.data);
   393	            updatedStat.setCount(updatedStat.getCount() + countDiff);
   394	            updatedStat.setBytes(updatedStat.getBytes() + bytesDiff);
   395	            statNode.data = updatedStat.getStatsBytes();
   396	        }
   397	    }
