   667	    /**
   668	     * If there is a quota set, return the appropriate prefix for that quota
   669	     * Else return null
   670	     * @param path The ZK path to check for quota
   671	     * @return Max quota prefix, or null if none
   672	     */
   673	    public String getMaxPrefixWithQuota(String path) {
   674	        // do nothing for the root.
   675	        // we are not keeping a quota on the zookeeper
   676	        // root node for now.
   677	        String lastPrefix = pTrie.findMaxPrefix(path);
   678	
   679	        if (rootZookeeper.equals(lastPrefix) || lastPrefix.isEmpty()) {
   680	            return null;
   681	        } else {
   682	            return lastPrefix;
   683	        }
   684	    }
