   819	
   820	        /**
   821	         * Equality is defined as the clientId and the cxid being the same. This
   822	         * allows us to use hash tables to track completion of transactions.
   823	         *
   824	         * @see java.lang.Object#equals(java.lang.Object)
   825	         */
   826	        @Override
   827	        public boolean equals(Object o) {
   828	            if (o instanceof ProcessTxnResult) {
   829	                ProcessTxnResult other = (ProcessTxnResult) o;
   830	                return other.clientId == clientId && other.cxid == cxid;
   831	            }
   832	            return false;
   833	        }
   834	
   835	        /**
   836	         * See equals() to find the rationale for how this hashcode is generated.
   837	         *
   838	         * @see ProcessTxnResult#equals(Object)
   839	         * @see java.lang.Object#hashCode()
   840	         */
   841	        @Override
   842	        public int hashCode() {
