   860	    public ProcessTxnResult processTxn(TxnHeader header, Record txn, boolean isSubTxn) {
   861	        ProcessTxnResult rc = new ProcessTxnResult();
   862	
   863	        try {
   864	            rc.clientId = header.getClientId();
   865	            rc.cxid = header.getCxid();
   866	            rc.zxid = header.getZxid();
   867	            rc.type = header.getType();
   868	            rc.err = 0;
   869	            rc.multiResult = null;
   870	            switch (header.getType()) {
   871	            case OpCode.create:
   872	                CreateTxn createTxn = (CreateTxn) txn;
   873	                rc.path = createTxn.getPath();
   874	                createNode(
   875	                    createTxn.getPath(),
   876	                    createTxn.getData(),
   877	                    createTxn.getAcl(),
   878	                    createTxn.getEphemeral() ? header.getClientId() : 0,
   879	                    createTxn.getParentCVersion(),
   880	                    header.getZxid(),
   881	                    header.getTime(),
   882	                    null);
   883	                break;
   884	            case OpCode.create2:
   885	                CreateTxn create2Txn = (CreateTxn) txn;
   886	                rc.path = create2Txn.getPath();
   887	                Stat stat = new Stat();
   888	                createNode(
   889	                    create2Txn.getPath(),
   890	                    create2Txn.getData(),
   891	                    create2Txn.getAcl(),
   892	                    create2Txn.getEphemeral() ? header.getClientId() : 0,
   893	                    create2Txn.getParentCVersion(),
   894	                    header.getZxid(),
   895	                    header.getTime(),
   896	                    stat);
   897	                rc.stat = stat;
   898	                break;
   899	            case OpCode.createTTL:
   900	                CreateTTLTxn createTtlTxn = (CreateTTLTxn) txn;
   901	                rc.path = createTtlTxn.getPath();
   902	                stat = new Stat();
   903	                createNode(
   904	                    createTtlTxn.getPath(),
   905	                    createTtlTxn.getData(),
   906	                    createTtlTxn.getAcl(),
   907	                    EphemeralType.TTL.toEphemeralOwner(createTtlTxn.getTtl()),
   908	                    createTtlTxn.getParentCVersion(),
   909	                    header.getZxid(),
   910	                    header.getTime(),
   911	                    stat);
   912	                rc.stat = stat;
   913	                break;
   914	            case OpCode.createContainer:
   915	                CreateContainerTxn createContainerTxn = (CreateContainerTxn) txn;
   916	                rc.path = createContainerTxn.getPath();
   917	                stat = new Stat();
   918	                createNode(
   919	                    createContainerTxn.getPath(),
   920	                    createContainerTxn.getData(),
   921	                    createContainerTxn.getAcl(),
   922	                    EphemeralType.CONTAINER_EPHEMERAL_OWNER,
   923	                    createContainerTxn.getParentCVersion(),
   924	                    header.getZxid(),
   925	                    header.getTime(),
   926	                    stat);
   927	                rc.stat = stat;
   928	                break;
   929	            case OpCode.delete:
   930	            case OpCode.deleteContainer:
   931	                DeleteTxn deleteTxn = (DeleteTxn) txn;
   932	                rc.path = deleteTxn.getPath();
   933	                deleteNode(deleteTxn.getPath(), header.getZxid());
   934	                break;
   935	            case OpCode.reconfig:
   936	            case OpCode.setData:
   937	                SetDataTxn setDataTxn = (SetDataTxn) txn;
   938	                rc.path = setDataTxn.getPath();
   939	                rc.stat = setData(
   940	                    setDataTxn.getPath(),
   941	                    setDataTxn.getData(),
   942	                    setDataTxn.getVersion(),
   943	                    header.getZxid(),
   944	                    header.getTime());
   945	                break;
   946	            case OpCode.setACL:
   947	                SetACLTxn setACLTxn = (SetACLTxn) txn;
   948	                rc.path = setACLTxn.getPath();
   949	                rc.stat = setACL(setACLTxn.getPath(), setACLTxn.getAcl(), setACLTxn.getVersion());
   950	                break;
   951	            case OpCode.closeSession:
   952	                long sessionId = header.getClientId();
   953	                if (txn != null) {
   954	                    killSession(sessionId, header.getZxid(),
   955	                            ephemerals.remove(sessionId),
   956	                            ((CloseSessionTxn) txn).getPaths2Delete());
   957	                } else {
   958	                    killSession(sessionId, header.getZxid());
   959	                }
   960	                break;
   961	            case OpCode.error:
   962	                ErrorTxn errTxn = (ErrorTxn) txn;
   963	                rc.err = errTxn.getErr();
   964	                break;
   965	            case OpCode.check:
   966	                CheckVersionTxn checkTxn = (CheckVersionTxn) txn;
   967	                rc.path = checkTxn.getPath();
   968	                break;
   969	            case OpCode.multi:
   970	                MultiTxn multiTxn = (MultiTxn) txn;
   971	                List<Txn> txns = multiTxn.getTxns();
   972	                rc.multiResult = new ArrayList<>();
   973	                boolean failed = false;
   974	                for (Txn subtxn : txns) {
   975	                    if (subtxn.getType() == OpCode.error) {
   976	                        failed = true;
   977	                        break;
   978	                    }
   979	                }
   980	
   981	                boolean post_failed = false;
   982	                for (Txn subtxn : txns) {
   983	                    final Supplier<Record> supplier;
   984	                    switch (subtxn.getType()) {
   985	                    case OpCode.create:
   986	                    case OpCode.create2:
   987	                        supplier = CreateTxn::new;
   988	                        break;
   989	                    case OpCode.createTTL:
   990	                        supplier = CreateTTLTxn::new;
   991	                        break;
   992	                    case OpCode.createContainer:
   993	                        supplier = CreateContainerTxn::new;
   994	                        break;
   995	                    case OpCode.delete:
   996	                    case OpCode.deleteContainer:
   997	                        supplier = DeleteTxn::new;
   998	                        break;
   999	                    case OpCode.setData:
  1000	                        supplier = SetDataTxn::new;
  1001	                        break;
  1002	                    case OpCode.error:
  1003	                        supplier = ErrorTxn::new;
  1004	                        post_failed = true;
  1005	                        break;
  1006	                    case OpCode.check:
  1007	                        supplier = CheckVersionTxn::new;
  1008	                        break;
  1009	                    default:
  1010	                        throw new IOException("Invalid type of op: " + subtxn.getType());
  1011	                    }
  1012	
  1013	                    final Record record;
  1014	                    if (failed && subtxn.getType() != OpCode.error) {
  1015	                        int ec = post_failed ? Code.RUNTIMEINCONSISTENCY.intValue() : Code.OK.intValue();
  1016	                        subtxn.setType(OpCode.error);
  1017	                        record = new ErrorTxn(ec);
  1018	                    } else {
  1019	                        record = RequestRecord.fromBytes(subtxn.getData()).readRecord(supplier);
  1020	                    }
  1021	
  1022	                    assert !failed || (subtxn.getType() == OpCode.error);
  1023	
  1024	                    TxnHeader subHdr = new TxnHeader(
  1025	                        header.getClientId(),
  1026	                        header.getCxid(),
  1027	                        header.getZxid(),
  1028	                        header.getTime(),
  1029	                        subtxn.getType());
  1030	                    ProcessTxnResult subRc = processTxn(subHdr, record, true);
  1031	                    rc.multiResult.add(subRc);
  1032	                    if (subRc.err != 0 && rc.err == 0) {
  1033	                        rc.err = subRc.err;
  1034	                    }
  1035	                }
  1036	                break;
  1037	            }
  1038	        } catch (KeeperException e) {
  1039	            LOG.debug("Failed: {}:{}", header, txn, e);
  1040	            rc.err = e.code().intValue();
  1041	        } catch (IOException e) {
  1042	            LOG.debug("Failed: {}:{}", header, txn, e);
  1043	        }
  1044	
  1045	        /*
  1046	         * Snapshots are taken lazily. When serializing a node, it's data
  1047	         * and children copied in a synchronization block on that node,
  1048	         * which means newly created node won't be in the snapshot, so
  1049	         * we won't have mismatched cversion and pzxid when replaying the
  1050	         * createNode txn.
  1051	         *
  1052	         * But there is a tricky scenario that if the child is deleted due
  1053	         * to session close and re-created in a different global session
  1054	         * after that the parent is serialized, then when replay the txn
  1055	         * because the node belongs to a different session, replay the
  1056	         * closeSession txn won't delete it anymore, and we'll get NODEEXISTS
  1057	         * error when replay the createNode txn. In this case, we need to
  1058	         * update the cversion and pzxid to the new value.
  1059	         *
  1060	         * Note, such failures on DT should be seen only during
  1061	         * restore.
  1062	         */
  1063	        if (header.getType() == OpCode.create && rc.err == Code.NODEEXISTS.intValue()) {
  1064	            LOG.debug("Adjusting parent cversion for Txn: {} path: {} err: {}", header.getType(), rc.path, rc.err);
  1065	            int lastSlash = rc.path.lastIndexOf('/');
  1066	            String parentName = rc.path.substring(0, lastSlash);
  1067	            CreateTxn cTxn = (CreateTxn) txn;
  1068	            try {
  1069	                setCversionPzxid(parentName, cTxn.getParentCVersion(), header.getZxid());
  1070	            } catch (NoNodeException e) {
  1071	                LOG.error("Failed to set parent cversion for: {}", parentName, e);
  1072	                rc.err = e.code().intValue();
  1073	            }
  1074	        } else if (rc.err != Code.OK.intValue()) {
  1075	            LOG.debug("Ignoring processTxn failure hdr: {} : error: {}", header.getType(), rc.err);
  1076	        }
  1077	
  1078	        /*
  1079	         * Things we can only update after the whole txn is applied to data
  1080	         * tree.
  1081	         *
  1082	         * If we update the lastProcessedZxid with the first sub txn in multi
  1083	         * and there is a snapshot in progress, it's possible that the zxid
  1084	         * associated with the snapshot only include partial of the multi op.
  1085	         *
  1086	         * When loading snapshot, it will only load the txns after the zxid
  1087	         * associated with snapshot file, which could cause data inconsistency
  1088	         * due to missing sub txns.
  1089	         *
  1090	         * To avoid this, we only update the lastProcessedZxid when the whole
  1091	         * multi-op txn is applied to DataTree.
  1092	         */
  1093	        if (!isSubTxn) {
  1094	            /*
  1095	             * A snapshot might be in progress while we are modifying the data
  1096	             * tree. If we set lastProcessedZxid prior to making corresponding
  1097	             * change to the tree, then the zxid associated with the snapshot
  1098	             * file will be ahead of its contents. Thus, while restoring from
  1099	             * the snapshot, the restore method will not apply the transaction
  1100	             * for zxid associated with the snapshot file, since the restore
  1101	             * method assumes that transaction to be present in the snapshot.
  1102	             *
  1103	             * To avoid this, we first apply the transaction and then modify
  1104	             * lastProcessedZxid.  During restore, we correctly handle the
  1105	             * case where the snapshot contains data ahead of the zxid associated
  1106	             * with the file.
  1107	             */
  1108	            if (rc.zxid > lastProcessedZxid) {
  1109	                lastProcessedZxid = rc.zxid;
  1110	            }
  1111	
  1112	            if (digestFromLoadedSnapshot != null) {
  1113	                compareSnapshotDigests(rc.zxid);
  1114	            } else {
  1115	                // only start recording digest when we're not in fuzzy state
  1116	                logZxidDigest(rc.zxid, getTreeDigest());
  1117	            }
  1118	        }
  1119	
  1120	        return rc;
  1121	    }
