  1276	    /**
  1277	     * this method sets up the path trie and sets up stats for quota nodes
  1278	     */
  1279	    private void setupQuota() {
  1280	        String quotaPath = Quotas.quotaZookeeper;
  1281	        DataNode node = getNode(quotaPath);
  1282	        if (node == null) {
  1283	            return;
  1284	        }
  1285	        traverseNode(quotaPath);
  1286	    }
