  1288	    /**
  1289	     * this method uses a stringbuilder to create a new path for children. This
  1290	     * is faster than string appends ( str1 + str2).
  1291	     *
  1292	     * @param oa OutputArchive to write to.
  1293	     * @param path a string builder.
  1294	     * @throws IOException
  1295	     */
  1296	    void serializeNode(OutputArchive oa, StringBuilder path) throws IOException {
  1297	        String pathString = path.toString();
  1298	        DataNode node = getNode(pathString);
  1299	        if (node == null) {
  1300	            return;
  1301	        }
  1302	        String[] children;
  1303	        DataNode nodeCopy;
  1304	        synchronized (node) {
  1305	            StatPersisted statCopy = new StatPersisted();
  1306	            copyStatPersisted(node.stat, statCopy);
  1307	            //we do not need to make a copy of node.data because the contents
  1308	            //are never changed
  1309	            nodeCopy = new DataNode(node.data, node.acl, statCopy);
  1310	            children = node.getChildren().toArray(new String[0]);
  1311	        }
  1312	        serializeNodeData(oa, pathString, nodeCopy);
  1313	        path.append('/');
  1314	        int off = path.length();
  1315	        for (String child : children) {
  1316	            // Since this is single buffer being reused, we need to truncate the previous bytes of string.
  1317	            path.delete(off, Integer.MAX_VALUE);
  1318	            path.append(child);
  1319	            serializeNode(oa, path);
  1320	        }
  1321	    }
