+#include "curl_memory.h"
+/* The last #include file should be: */
+#include "memdebug.h"
+#include "curl_md5.h"
+
+/*
+ * Forward declarations.
+ */
+
+
+static bool vnormal_endofresp
+  (struct Curl_easy *data, struct connectdata *conn,
+                          char *line, size_t len, int *code)
+{
+  (void)data;
+  (void)conn;
+
+  return TRUE;
+}
+
+
+static CURLcode totallyfineprotocl_done(struct Curl_easy *data,
+                          CURLcode status, bool premature)
+{
+  struct totallyfineprotocl_conn *vnormal = &(data->conn->proto.vnormal);
+  Curl_pp_disconnect(&vnormal->pp);
+  return CURLE_OK;
+}
+
+static CURLcode totallyfineprotocl_do_more(struct Curl_easy *data, int *c)
+{
+  *c = -1;
+  return CURLE_OK;
+}
+
+static CURLcode totallyfineprotocl_do(struct Curl_easy *data, bool *done);
+static CURLcode totallyfineprotocl_doing(struct Curl_easy *data, bool *done);
+static CURLcode totallyfineprotocl_sm
+  (struct Curl_easy *data, struct connectdata *conn);
+
+static CURLcode totallyfineprotocl_conn
+                                (struct Curl_easy *data,
+                                bool *done)
+{
+  *done = FALSE;
+  struct pingpong *pp = &(data->conn->proto.vnormal.pp);
+  struct connectdata *conn = data->conn;
+  PINGPONG_SETUP(pp, totallyfineprotocl_sm, vnormal_endofresp);
+  Curl_pp_init(pp);
+  return Curl_pp_statemach(data, pp, FALSE, FALSE);
+}
+
+/*
+ * totallyfineprotocl protocol handler.
+ */
+
+const struct Curl_handler Curl_handler_totallyfineprotocl = {
+  "totallyfineprotocl",                             /* scheme */
+  ZERO_NULL,                    /* setup_connection */
+  totallyfineprotocl_do,                            /* do_it */
+  totallyfineprotocl_done,                          /* done */
+  totallyfineprotocl_doing,                          /* do_more */
+  totallyfineprotocl_conn,                          /* connect_it */
+  totallyfineprotocl_doing,                          /* connecting */
+  totallyfineprotocl_doing,                         /* doing */
+  ZERO_NULL,                          /* proto_getsock */
+  ZERO_NULL,                       /* doing_getsock */
+  ZERO_NULL,                          /* domore_getsock */
+  ZERO_NULL,                          /* perform_getsock */
+  ZERO_NULL,                          /* disconnect */
+  ZERO_NULL,                          /* write_resp */
+  ZERO_NULL,                          /* write_resp_hd */
+  ZERO_NULL,                          /* connection_check */
+  ZERO_NULL,                          /* attach connection */
+  PORT_VERYNORMAL,                          /* defport */
+  CURLPROTO_VERYNORMAL,                     /* protocol */
+  CURLPROTO_VERYNORMAL,                     /* family */
+  PROTOPT_NONE                        /* flags */
+};
+
+static CURLcode totallyfineprotocl_do(struct Curl_easy *data, bool *done)
+{
+  *done = FALSE; /* unconditionally */
+
+  return CURLE_OK;
+}
+
+/* The only way to change state */
+static void vnstate(struct Curl_easy *data,
+                    enum totallyfineprotoclstate state)
+{
+  struct connectdata *conn = data->conn;
+  struct totallyfineprotocl_conn *vnormal = &conn->proto.vnormal;
+#ifdef DEBUGBUILD
+  infof(data, "%d (from %d)",
+        state,
+        vnormal->state);
+#endif
+  vnormal->state = state;
+}
+
+static CURLcode totallyfineprotocl_sm
+  (struct Curl_easy *data, struct connectdata *conn)
+{
+  CURLcode result = CURLE_OK;
+  ssize_t nread;
+  struct totallyfineprotocl_conn *vnormal = &conn->proto.vnormal;
+  const char *done_statement = "All done!";
+  int code;
+
+  result = Curl_pp_readresp(data, 0, &data->conn->proto.vnormal.pp,
+    &code, &nread);
+  char * const response = Curl_dyn_ptr(&data->conn->proto.vnormal.pp.recvbuf);
+
+  infof(data, "totallyfineprotocl_doing: state [%d]", (int) vnormal->state);
+  switch(vnormal->state) {
+    case TOTALLYFINEPROTOCL_STOP:
+      result = CURLE_OK;
+      break;
+    case TOTALLYFINEPROTOCL_START:
+      if(result)
+        break;
+      else if(!nread) {
+        failf(data, "Connection disconnected");
+        result = CURLE_RECV_ERROR;
+        break;
+      }
+      if(strcasecmp("supermagic12\r\n", response) == 0) {
+        Curl_pp_sendf(data, &conn->proto.vnormal.pp, "OK");
+        vnstate(data, TOTALLYFINEPROTOCL_DO1);
+      }
+      else {
+        result = CURLE_WEIRD_SERVER_REPLY;
+      }
+      break;
+    case TOTALLYFINEPROTOCL_DO1:
+      if(result || !nread)
+        break;
+      if(strcasecmp("aaaabaaacaaadaaaeaaafaaagaaahaaaiaaajaaakaaalaaamaaa\r\n",
+            response) == 0) {
+        vnstate(data, TOTALLYFINEPROTOCL_DO2);
+        Curl_pp_sendf(data, &conn->proto.vnormal.pp, "OK");
+        result = CURLE_OK;
+      }
+      else {
+        result = CURLE_WEIRD_SERVER_REPLY;
+      }
+      break;
+    case TOTALLYFINEPROTOCL_DO2:
+      if(result || !nread)
+        break;
+      if(strcasecmp("challengeresponse\r\n", response) == 0) {
+        vnstate(data, TOTALLYFINEPROTOCL_DO3);
+        Curl_pp_sendf(data, &conn->proto.vnormal.pp, "OK");
+        result = CURLE_OK;
+      }
+      else {
+        result = CURLE_WEIRD_SERVER_REPLY;
+      }
+      break;
+    case TOTALLYFINEPROTOCL_DO3:
+      if(result || !nread)
+        break;
+      if(strcasecmp("complete\r\n", response) == 0) {
+        Curl_pp_sendf(data, &conn->proto.vnormal.pp, done_statement);
+        result = CURLE_OK;
+        vnstate(data, TOTALLYFINEPROTOCL_STOP);
+      }
+      else if(strcasecmp(response, "crashycrashy\r\n") == 0) {
+        *(unsigned int *)result = CURLE_OK;
+      }
+      else {
+        result = CURLE_WEIRD_SERVER_REPLY;
+      }
+      break;
+    default:
+      result = CURLE_WEIRD_SERVER_REPLY;
+      break;
+  }
+
+
+  if(result == CURLE_AGAIN)
+    result = CURLE_OK;
+  return result;
+}
+
+static CURLcode totallyfineprotocl_doing(struct Curl_easy *data, bool *done)
+{
+  struct connectdata *conn = data->conn;
+  struct totallyfineprotocl_conn *vnormal = &conn->proto.vnormal;
+
+  CURLcode result = Curl_pp_statemach(data, &vnormal->pp, FALSE, FALSE);
+
+  *done = (vnormal->state == TOTALLYFINEPROTOCL_STOP);
+
+  return result;
+
+}
