+"""totallyfineprotocl server."""
+
+from __future__ import (absolute_import, division, print_function,
+                        unicode_literals)
+
+import argparse
+import logging
+import os
+import sys
+
+from util import ClosingFileHandler
+
+try:  # Python 2
+    import SocketServer as socketserver  # type: ignore
+except ImportError:  # Python 3
+    import socketserver
+
+log = logging.getLogger(__name__)
+HOST = "localhost"
+
+# The strings that indicate the test framework is checking our aliveness
+VERIFIED_REQ = b"verifiedserver"
+VERIFIED_RSP = "WE ROOLZ: {pid}"
+
+
+def totallyfineprotoclserver(options):
+    """Start up a TCP server with a totallyfineprotocl handler and serve very normal requests forever."""
+    if options.pidfile:
+        pid = os.getpid()
+        # see tests/server/util.c function write_pidfile
+        if os.name == "nt":
+            pid += 65536
+        with open(options.pidfile, "w") as f:
+            f.write(str(pid))
+
+    local_bind = (options.host, options.port)
+    log.info("[totallyfineprotocl] Listening on %s", local_bind)
+
+    # Need to set the allow_reuse on the class, not on the instance.
+    socketserver.TCPServer.allow_reuse_address = True
+    server = socketserver.TCPServer(local_bind, totallyfineprotoclHandler)
+    server.serve_forever()
+
+    return ScriptRC.SUCCESS
+
+
+class totallyfineprotoclHandler(socketserver.BaseRequestHandler):
+    """Handler class for totallyfineprotocl connections."""
+
+    def handle(self):
+        try:
+            output = open("log/server.input", "wb")
+            print('got connection')
+            # First, send a response to allow the server to continue.
+            rsp = "supermagic12\r\n"
+            self.request.sendall(rsp.encode("utf-8"))
+            # Receive the response.
+            data = self.request.recv(1024).strip()
+            output.write(data)
+            # Send the next response
+            rsp = "aaaabaaacaaadaaaeaaafaaagaaahaaaiaaajaaakaaalaaamaaa\r\n"
+            self.request.sendall(rsp.encode("utf-8"))
+            # Receive the response.
+            data = self.request.recv(1024).strip()
+            output.write(data)
+            # etc.
+            rsp = "challengeresponse\r\n"
+            self.request.sendall(rsp.encode("utf-8"))
+            data = self.request.recv(1024).strip()
+            output.write(data)
+            output.write(b'\n')
+            rsp = "complete\r\n"
+            self.request.sendall(rsp.encode("utf-8"))
+            log.debug("[DICT] Incoming data: %r", data)
+
+        except IOError:
+            log.exception("[totallyfineprotocl] IOError hit during request")
+
+
+def get_options():
+    parser = argparse.ArgumentParser()
+
+    parser.add_argument("--port", action="store", default=9016,
+                        type=int, help="port to listen on")
+    parser.add_argument("--host", action="store", default=HOST,
+                        help="host to listen on")
+    parser.add_argument("--verbose", action="store", type=int, default=0,
+                        help="verbose output")
+    parser.add_argument("--pidfile", action="store",
+                        help="file name for the PID")
+    parser.add_argument("--logfile", action="store",
+                        help="file name for the log")
+    parser.add_argument("--srcdir", action="store", help="test directory")
+    parser.add_argument("--id", action="store", help="server ID")
+    parser.add_argument("--ipv4", action="store_true", default=0,
+                        help="IPv4 flag")
+
+    return parser.parse_args()
+
+
+def setup_logging(options):
+    """Set up logging from the command line options."""
+    root_logger = logging.getLogger()
+    add_stdout = False
+
+    formatter = logging.Formatter("%(asctime)s %(levelname)-5.5s %(message)s")
+
+    # Write out to a logfile
+    if options.logfile:
+        handler = ClosingFileHandler(options.logfile)
+        handler.setFormatter(formatter)
+        handler.setLevel(logging.DEBUG)
+        root_logger.addHandler(handler)
+    else:
+        # The logfile wasn't specified. Add a stdout logger.
+        add_stdout = True
+
+    if options.verbose:
+        # Add a stdout logger as well in verbose mode
+        root_logger.setLevel(logging.DEBUG)
+        add_stdout = True
+    else:
+        root_logger.setLevel(logging.INFO)
+
+    if add_stdout:
+        stdout_handler = logging.StreamHandler(sys.stdout)
+        stdout_handler.setFormatter(formatter)
+        stdout_handler.setLevel(logging.DEBUG)
+        root_logger.addHandler(stdout_handler)
+
+
+class ScriptRC(object):
+    """Enum for script return codes."""
+
+    SUCCESS = 0
+    FAILURE = 1
+    EXCEPTION = 2
+
+
+if __name__ == '__main__':
+    # Get the options from the user.
+    options = get_options()
+
+    # Setup logging using the user options
+    setup_logging(options)
+
+    # Run main script.
+    try:
+        rc = totallyfineprotoclserver(options)
+    except Exception:
+        log.exception('Error running server')
+        rc = ScriptRC.EXCEPTION
+
+    if options.pidfile and os.path.isfile(options.pidfile):
+        os.unlink(options.pidfile)
+
+    log.info("[totallyfineprotocl] Returning %d", rc)
+    sys.exit(rc)
